  ('ee3f5025-63c5-4f6d-8c94-2061bfb907f6'::uuid, 'a0000000-0000-4000-8000-000000000304'::uuid, 'OH', 'commercial', '99341', 'modifier_required', '{"answer":"Modifier 25 is required on the E/M when a significant, separately identifiable E&M service is performed by the same provider on the same date as another procedure or service, including an E&M that led to the decision to perform a minor surgery. This is the modifier that unbundles a home-visit E/M from a same-day minor procedure. The manual warns that without required modifiers the service cannot be correctly defined and that omitting a required modifier may result in processing delays or an incorrect reimbursement amount. Up to four modifiers may be assigned to one CPT code.","appliesToService":"significant, separately identifiable Evaluation and Management (E&M) service performed by the same provider on the same date of service as another procedure or service","mappedFrom":"service-level rule mapped to this code","sourceDocument":"Medical Mutual of Ohio — Provider Manual (October 2025, Z6640 R10/25)","supportingQuotes":[]}'::jsonb, 'unknown', 0.75, DATE '2026-01-01', NULL, 'f1000000-0006-4000-8000-00000000a006'::uuid, 'an E&M that resulted in a decision to perform a minor surgery', 'extract:round3-six-payers-2026-08'),
  ('6aa010aa-3a22-4a9f-894e-9cdf2238662d'::uuid, 'a0000000-0000-4000-8000-000000000304'::uuid, 'OH', 'commercial', '99342', 'modifier_required', '{"answer":"Modifier 25 is required on the E/M when a significant, separately identifiable E&M service is performed by the same provider on the same date as another procedure or service, including an E&M that led to the decision to perform a minor surgery. This is the modifier that unbundles a home-visit E/M from a same-day minor procedure. The manual warns that without required modifiers the service cannot be correctly defined and that omitting a required modifier may result in processing delays or an incorrect reimbursement amount. Up to four modifiers may be assigned to one CPT code.","appliesToService":"significant, separately identifiable Evaluation and Management (E&M) service performed by the same provider on the same date of service as another procedure or service","mappedFrom":"service-level rule mapped to this code","sourceDocument":"Medical Mutual of Ohio — Provider Manual (October 2025, Z6640 R10/25)","supportingQuotes":[]}'::jsonb, 'unknown', 0.75, DATE '2026-01-01', NULL, 'f1000000-0006-4000-8000-00000000a006'::uuid, 'an E&M that resulted in a decision to perform a minor surgery', 'extract:round3-six-payers-2026-08'),
